inline const char* contextsJson="{\"34\":{\"context_ref\":{\"path\":\"Build/fullscope-private-a-r01/level034-r05/level-source-context.json\",\"bytes\":11428,\"sha256\":\"5184bc9f5fc18ee26c1d2450ba4705768b5bae1f3dc8eda0991bef772986daea\"},\"source_context\":{\"level\":34,\"originals\":{\"level\":34,\"txt\":{\"path\":\"Notes/music/guitar project/TXT version/Scale_Exercises_Section_IV_Level_34_Major_Pentatonic_Five_Position_Connection_Fixed_Key_A_Neck_Map.txt\",\"bytes\":21711,\"sha256\":\"e4d015b5f553691f1fd108702b36a538182c2d35b9b457b70c34306b16312724\"},\"pdf\":{\"path\":\"Notes/music/guitar project/PDF version/Scale_Exercises_Section_IV_Level_34_Major_Pentatonic_Five_Position_Connection_Fixed_Key_A_Neck_Map.pdf\",\"bytes\":34668,\"sha256\":\"d4c1833abf92748214cc61054f51683c994edd14048d16046a6cc619b9031a8e\"}},\"guidance_lines\":[{\"line\":1,\"text\":\"SCALE EXERCISES - SECTION IV, LEVEL 34\"},{\"line\":2,\"text\":\"A MAJOR PENTATONIC FIVE-POSITION CONNECTION - FIXED-KEY NECK MAP\"},{\"line\":3,\"text\":\"\"},{\"line\":4,\"text\":\"PURPOSE\"},{\"line\":5,\"text\":\"Stop transposing one shape. Keep the key fixed as A major pentatonic and move through five common\"},{\"line\":6,\"text\":\"positions from the low-E root frame at frets 4-7 through the octave frame at frets 14-17. Learn each\"},{\"line\":7,\"text\":\"vertical position, connect adjacent positions around one shared anchor note on every string, then link\"},{\"line\":8,\"text\":\"all five frames in a forward and reverse zigzag.\"},{\"line\":9,\"text\":\"\"},{\"line\":10,\"text\":\"IMPORTANT POSITION-LABEL NOTE\"},{\"line\":11,\"text\":\"Pentatonic box numbers vary among methods. This workbook numbers positions in ascending-neck order,\"},{\"line\":12,\"text\":\"beginning with the A-root frame around low-E fret 5. Use the fret spans, degree maps, and root locations\"},{\"line\":13,\"text\":\"as the authoritative identity of each position.\"},{\"line\":14,\"text\":\"\"},{\"line\":15,\"text\":\"A MAJOR-PENTATONIC FORMULA\"},{\"line\":16,\"text\":\"Notes: A B C# E F#\"},{\"line\":17,\"text\":\"Degrees: 1 2 3 5 6\"},{\"line\":18,\"text\":\"Intervals: whole - whole - minor third - whole - minor third\"},{\"line\":19,\"text\":\"\"},{\"line\":20,\"text\":\"POSITION SUMMARY\"},{\"line\":21,\"text\":\"P1 ROOT FRAME             frets 4-7    starts degree 1  roots E5, D7, e5\"},{\"line\":22,\"text\":\"    Ascending degrees: 1 2 3 5 6 1 2 3 5 6 1 2\"},{\"line\":23,\"text\":\"P2 SECOND-DEGREE FRAME    frets 6-10   starts degree 2  roots D7, B10\"},{\"line\":24,\"text\":\"    Ascending degrees: 2 3 5 6 1 2 3 5 6 1 2 3\"},{\"line\":25,\"text\":\"P3 THIRD-DEGREE FRAME     frets 9-12   starts degree 3  roots A12, B10\"},{\"line\":26,\"text\":\"    Ascending degrees: 3 5 6 1 2 3 5 6 1 2 3 5\"},{\"line\":27,\"text\":\"P4 FIFTH-DEGREE FRAME     frets 11-14  starts degree 5  roots A12, G14\"},{\"line\":28,\"text\":\"    Ascending degrees: 5 6 1 2 3 5 6 1 2 3 5 6\"},{\"line\":29,\"text\":\"P5 SIXTH-DEGREE FRAME     frets 14-17  starts degree 6  roots E17, G14, e17\"},{\"line\":30,\"text\":\"    Ascending degrees: 6 1 2 3 5 6 1 2 3 5 6 1\"},{\"line\":31,\"text\":\"\"},{\"line\":32,\"text\":\"PICKING AND COUNTS\"},{\"line\":33,\"text\":\"Each vertical position cell contains 24 notes: 12 ascending and 12 descending with the high endpoint repeated.\"},{\"line\":34,\"text\":\"Each shared-anchor seam cell contains 30 notes: six five-note string groups. Every five-note group flips the\"},{\"line\":35,\"text\":\"starting stroke on the next string, but the complete 30-note cell is even.\"},{\"line\":36,\"text\":\"The forward zigzag contains 60 notes; the reverse zigzag contains 60 notes. Repeat high-e fret 17 at the\"},{\"line\":37,\"text\":\"turn when linking them, producing an even 120-note circuit.\"},{\"line\":38,\"text\":\"Five position cells = 120 notes. Four seam cells = 120 notes. Linked zigzag = 120 notes.\"},{\"line\":39,\"text\":\"Complete Level 34 workout = 360 notes.\"},{\"line\":40,\"text\":\"\"},{\"line\":41,\"text\":\"STRICT ALTERNATE PICKING\"},{\"line\":42,\"text\":\"Complete separate D-start and U-start passes. Do not restart at a string crossing, shared anchor, position\"},{\"line\":43,\"text\":\"boundary, root, outer-string turn, or the forward/reverse turnaround.\"},{\"line\":44,\"text\":\"\"},{\"line\":45,\"text\":\"========================================================================================================================\"},{\"line\":46,\"text\":\"FIVE VERTICAL POSITION CELLS\"},{\"line\":47,\"text\":\"========================================================================================================================\"},{\"line\":48,\"text\":\"\"}],\"hierarchy_reference\":{\"path\":\"Results/level-oracle/exercise-completeness-r01/range-a-r02/producer-r01/level034-hierarchy.json\",\"bytes\":29978,\"sha256\":\"a6b9778019ed061ae50f3eedfcd6a6503cf86f396a63d5fe2821e440014d2cdd\"},\"accepted_child_exclusions\":[[\"proposed-printed-l025-complete-tablature-rung-01-of-13-a-natural-minor-root-on-low-e-fret-5-frame-5-8\",\"printed:l025:complete-tablature:rung-01-of-13-a-natural-minor-root-on-low-e-fret-5-frame-5-8\"],[\"proposed-printed-l026-complete-tablature-rung-01-of-13-a-natural-minor-root-on-low-e-fret-5-frame-4-8\",\"printed:l026:complete-tablature:rung-01-of-13-a-natural-minor-root-on-low-e-fret-5-frame-4-8\"]],\"historical_source_only_units\":[],\"semantic_guidance\":{\"position_summary_text\":\"POSITION SUMMARY\\nP1 ROOT FRAME             frets 4-7    starts degree 1  roots E5, D7, e5\\n    Ascending degrees: 1 2 3 5 6 1 2 3 5 6 1 2\\nP2 SECOND-DEGREE FRAME    frets 6-10   starts degree 2  roots D7, B10\\n    Ascending degrees: 2 3 5 6 1 2 3 5 6 1 2 3\\nP3 THIRD-DEGREE FRAME     frets 9-12   starts degree 3  roots A12, B10\\n    Ascending degrees: 3 5 6 1 2 3 5 6 1 2 3 5\\nP4 FIFTH-DEGREE FRAME     frets 11-14  starts degree 5  roots A12, G14\\n    Ascending degrees: 5 6 1 2 3 5 6 1 2 3 5 6\\nP5 SIXTH-DEGREE FRAME     frets 14-17  starts degree 6  roots E17, G14, e17\\n    Ascending degrees: 6 1 2 3 5 6 1 2 3 5 6 1\",\"position_summary_ref\":\"L34-TXT1-20-30\",\"counts_picking_text\":\"PICKING AND COUNTS\\nEach vertical position cell contains 24 notes: 12 ascending and 12 descending with the high endpoint repeated.\\nEach shared-anchor seam cell contains 30 notes: six five-note string groups. Every five-note group flips the\\nstarting stroke on the next string, but the complete 30-note cell is even.\\nThe forward zigzag contains 60 notes; the reverse zigzag contains 60 notes. Repeat high-e fret 17 at the\\nturn when linking them, producing an even 120-note circuit.\\nFive position cells = 120 notes. Four seam cells = 120 notes. Linked zigzag = 120 notes.\\nComplete Level 34 workout = 360 notes.\\n\\nSTRICT ALTERNATE PICKING\\nComplete separate D-start and U-start passes. Do not restart at a string crossing, shared anchor, position\\nboundary, root, outer-string turn, or the forward/reverse turnaround.\\n\\n========================================================================================================================\\nFIVE VERTICAL POSITION CELLS\\n========================================================================================================================\",\"counts_picking_ref\":\"L34-TXT1-32-47\",\"seam_instruction_text\":\"For each string, play lower outer note -> shared anchor -> upper outer note -> shared anchor -> lower outer note.\\nStay in the lower-position fingering through note 2. Shift after the anchor sounds, play note 3 in the upper\\nframe, return to the anchor as note 4, then shift back before note 5. Do not re-articulate the anchor merely\\nto disguise the hand movement.\",\"seam_instruction_ref\":\"L34-TXT1-197-200\",\"forward_route_text\":\"Route: P1 ASC -> high-e 7 to 9 -> P2 DESC -> low-E 7 to 9 -> P3 ASC -> high-e 12 to 14 ->\\n       P4 DESC -> low-E 12 to 14 -> P5 ASC.\\nEvery position segment contains 12 notes, so every new frame begins with the same pick orientation.\",\"forward_route_ref\":\"L34-TXT1-253-255\",\"reverse_route_text\":\"Route: P5 DESC -> low-E 14 to 12 -> P4 ASC -> high-e 14 to 12 -> P3 DESC -> low-E 9 to 7 ->\\n       P2 ASC -> high-e 9 to 7 -> P1 DESC.\\nWhen linking forward and reverse, articulate high-e fret 17 at the end of the forward route and again to\\nbegin the reverse route. The linked circuit contains 120 notes and returns to low-E fret 5.\",\"reverse_route_ref\":\"L34-TXT1-310-313\",\"practice_mastery_text\":\"PRACTICE PROGRESSION\\n========================================================================================================================\\n1. Map P1-P5 and say each starting degree.\\n2. Play every 24-note vertical cell with both pick starts.\\n3. Learn all four 30-note shared-anchor seam cells.\\n4. Play the 60-note forward zigzag without a seam pause.\\n5. Play the 60-note reverse zigzag without a seam pause.\\n6. Link forward and reverse as one 120-note circuit.\\n7. Accent every A root, then remove the accents while continuing to hear A as tonic.\\n\\nERROR DIAGNOSIS\\nLOST KEY CENTER: Stop on the nearest A root, sing A, and restart the local frame.\\nWRONG BOX: Name the position span and its first low-E degree before playing.\\nEARLY SHIFT: Remain in the lower frame through the shared anchor; move only after it sounds.\\nNOISY SEAM: Release pressure, move the thumb with the hand, and reduce the tempo by 4-6 BPM.\\nPICK RESET: Mute the strings and air-pick the exact 12-, 30-, or 60-note count.\\nTENSION: Stop, shake out, and practice one seam instead of forcing the full route.\\n\\nADVANCEMENT RULES\\nAdd 2 BPM after three clean circuits at the current route length.\\nAfter two errors, reduce 4-6 BPM or shorten the route to one adjacent-position seam.\\nIncrease route length before speed when the shift is weak. Increase speed before route length when the map is secure.\\n\\nMASTERY GATE BEFORE LEVEL 35\\nName all five positions and fret spans; play each vertical cell with D-start and U-start; shift at every\\nshared anchor without a scrape or hesitation; complete the linked 120-note zigzag on two separate days;\\nidentify every A root by sight and sound; and recover the correct position after a deliberate random stop.\\n\",\"practice_mastery_ref\":\"L34-TXT1-366-393\",\"next_level_text\":\"NEXT LEVEL\\nLevel 35 isolates horizontal A-major-pentatonic motion along individual strings and converts the five\\nposition seams into controlled melodic shifts, slides, and destination-note landings.\",\"next_level_ref\":\"L34-TXT1-401-403\"},\"source_options_are_distinct\":true}},\"35\":{\"context_ref\":{\"path\":\"Build/fullscope-private-a-r01/level035-r06/level-source-context.json\",\"bytes\":13599,\"sha256\":\"4fc06adf81c15f9a0d5cf213b8bc5db83cad319433d17d092a70d9835bd3d63f\"},\"source_context\":{\"level\":35,\"originals\":{\"level\":35,\"txt\":{\"path\":\"Notes/music/guitar project/TXT version/Scale_Exercises_Section_IV_Level_35_Major_Pentatonic_Horizontal_String_Lanes_Controlled_Shifts_Slides_and_Destination_Landings_Fixed_Key_A.txt\",\"bytes\":17788,\"sha256\":\"4a6d7e608e4217a832e72ed6b17526f75567fddc82f8018f40bf96f868d6b684\"},\"pdf\":{\"path\":\"Notes/music/guitar project/PDF version/Scale_Exercises_Section_IV_Level_35_Major_Pentatonic_Horizontal_String_Lanes_Controlled_Shifts_Slides_and_Destination_Landings_Fixed_Key_A.pdf\",\"bytes\":37209,\"sha256\":\"90625b12ffac1d51d085f3b95cc12917fa2e6825f8137a83fec28d5ba468ea29\"}},\"guidance_lines\":[{\"line\":1,\"text\":\"SCALE EXERCISES - SECTION IV, LEVEL 35\"},{\"line\":2,\"text\":\"A MAJOR PENTATONIC HORIZONTAL STRING LANES - CONTROLLED SHIFTS, SLIDES, AND DESTINATION LANDINGS\"},{\"line\":3,\"text\":\"\"},{\"line\":4,\"text\":\"PURPOSE\"},{\"line\":5,\"text\":\"Keep the key fixed as A major pentatonic and turn the five vertical positions from Level 34 into six\"},{\"line\":6,\"text\":\"horizontal one-string melodies. First relocate silently between three two-note stations, then isolate one\"},{\"line\":7,\"text\":\"timed slide at each of the four position seams, then land directly on named destinations over increasing\"},{\"line\":8,\"text\":\"distances. Finish by linking all six strings in a forward and reverse horizontal snake.\"},{\"line\":9,\"text\":\"\"},{\"line\":10,\"text\":\"IMPORTANT INTERPRETATION\"},{\"line\":11,\"text\":\"This level does not transpose the shape. Every note belongs to A major pentatonic: A B C# E F#.\"},{\"line\":12,\"text\":\"The suggested route fingerings are designed for continuous one-string movement and therefore do not always\"},{\"line\":13,\"text\":\"match the vertical-box fingerings from Level 34. The fret, note, degree, and timing are authoritative.\"},{\"line\":14,\"text\":\"\"},{\"line\":15,\"text\":\"A MAJOR-PENTATONIC FORMULA\"},{\"line\":16,\"text\":\"Degrees: 1 2 3 5 6\"},{\"line\":17,\"text\":\"Notes:   A B C# E F#\"},{\"line\":18,\"text\":\"Intervals: whole - whole - minor third - whole - minor third\"},{\"line\":19,\"text\":\"\"},{\"line\":20,\"text\":\"HORIZONTAL LANE SUMMARY\"},{\"line\":21,\"text\":\"Low E   frets 5 7 9 12 14 17     degrees 1 2 3 5 6 1  notes A B C# E F# A    fingers 1 3 1 4 1 4 roots 5,17\"},{\"line\":22,\"text\":\"A       frets 4 7 9 12 14 16     degrees 3 5 6 1 2 3  notes C# E F# A B C#   fingers 1 4 1 4 1 3 roots 12\"},{\"line\":23,\"text\":\"D       frets 4 7 9 11 14 16     degrees 6 1 2 3 5 6  notes F# A B C# E F#   fingers 1 4 1 3 1 3 roots 7\"},{\"line\":24,\"text\":\"G       frets 4 6 9 11 14 16     degrees 2 3 5 6 1 2  notes B C# E F# A B    fingers 1 3 1 3 1 3 roots 14\"},{\"line\":25,\"text\":\"B       frets 5 7 10 12 14 17    degrees 5 6 1 2 3 5  notes E F# A B C# E    fingers 1 3 1 3 1 4 roots 10\"},{\"line\":26,\"text\":\"High e  frets 5 7 9 12 14 17     degrees 1 2 3 5 6 1  notes A B C# E F# A    fingers 1 3 1 4 1 4 roots 5,17\"},{\"line\":27,\"text\":\"\"},{\"line\":28,\"text\":\"PICKING AND COUNT RULES\"},{\"line\":29,\"text\":\"Module A: six 12-note picked cells = 72 picked notes.\"},{\"line\":30,\"text\":\"Module B: 24 slide phrases x 6 sounding tones = 144 sounding tones, but only 96 pick attacks.\"},{\"line\":31,\"text\":\"Module C: six 16-note destination ladders = 96 picked notes.\"},{\"line\":32,\"text\":\"Module D: forward 36 + reverse 36 = 72 picked notes.\"},{\"line\":33,\"text\":\"Complete Level 35 workout = 384 sounding tones / 336 pick attacks.\"},{\"line\":34,\"text\":\"\"},{\"line\":35,\"text\":\"STRICT ALTERNATE PICKING\"},{\"line\":36,\"text\":\"Complete separate D-start and U-start passes. Do not restart at a string change, station shift, seam slide,\"},{\"line\":37,\"text\":\"repeated destination, A root, or forward/reverse turnaround. A slide destination is sounded without a new\"},{\"line\":38,\"text\":\"pick attack and must arrive exactly on the subdivision.\"},{\"line\":39,\"text\":\"\"},{\"line\":40,\"text\":\"========================================================================================================================\"},{\"line\":41,\"text\":\"MODULE A - SIX SILENT-SHIFT HORIZONTAL LANES\"},{\"line\":42,\"text\":\"========================================================================================================================\"},{\"line\":43,\"text\":\"Group each lane into three two-note stations. Use finger 1-3 for a whole step and 1-4 for a minor third.\"},{\"line\":44,\"text\":\"Shift after the first station and after the second station. Release pressure before moving. No slide is allowed.\"},{\"line\":45,\"text\":\"\"}],\"hierarchy_reference\":{\"path\":\"Results/level-oracle/exercise-completeness-r01/range-a-r02/producer-r01/level035-hierarchy.json\",\"bytes\":38052,\"sha256\":\"6f498d38ecf803a87ba8ba1d9a4d8960665cf25044cd4c58076b97e4ccb5209a\"},\"accepted_child_exclusions\":[[\"proposed-printed-l025-complete-tablature-rung-01-of-13-a-natural-minor-root-on-low-e-fret-5-frame-5-8\",\"printed:l025:complete-tablature:rung-01-of-13-a-natural-minor-root-on-low-e-fret-5-frame-5-8\"],[\"proposed-printed-l026-complete-tablature-rung-01-of-13-a-natural-minor-root-on-low-e-fret-5-frame-4-8\",\"printed:l026:complete-tablature:rung-01-of-13-a-natural-minor-root-on-low-e-fret-5-frame-4-8\"]],\"historical_source_only_units\":[],\"semantic_guidance\":{\"txt\":\"PRACTICE PROGRESSION\\n========================================================================================================================\\n1. Map all six lanes and say notes plus degrees.\\n2. Play one Module A lane at one note per click.\\n3. Complete all six silent-shift cells with both pick starts.\\n4. Add one seam-slide page; count 6 tones but only 4 attacks per string.\\n5. Complete Module C with finger 1 and no audible relocation.\\n6. Play the 36-note forward snake without a pause.\\n7. Play the 36-note reverse snake without a pause.\\n8. Link the 72-note circuit and accent every A root, then remove the accents.\\n\\nERROR DIAGNOSIS\\nNOISY SHIFT: release earlier, move the thumb with the hand, and reduce 4-6 BPM.\\nLATE SLIDE: shorten the motion and practice the anchor-to-target pair alone.\\nFRET FISHING: name and look at the destination before leaving the launch note.\\nPICK RESET: mute the strings and air-pick the exact 12-, 36-, or 72-note count.\\nTENSION: stop the full route and return to one string.\\n\\nADVANCEMENT RULES\\nAdd 2 BPM after three clean runs at the current route length. After two errors, reduce 4-6 BPM or shorten\\nthe route to one lane or seam. Increase route length before speed when the map is weak. Increase speed\\nbefore route length only when every destination is already secure.\\n\\nMASTERY GATE BEFORE LEVEL 36\\nName the six notes and degrees on every string; play all six Module A lanes with D-start and U-start;\\nexecute all 24 seam-slide phrases without an extra pick or late arrival; land on every printed destination\\nwithout an audible search; complete the linked 72-note snake on two separate days; identify every A root\\nby sight and sound; and recover the correct lane after a deliberate random stop.\\n\\nPRACTICE LOG\\nDate | Focus | D/U | BPM | Clean? | Weak lane / seam / target | Next target\\n____ | _____ | ___ | ___ | ______ | _________________________ | ___________\\n____ | _____ | ___ | ___ | ______ | _________________________ | ___________\\n____ | _____ | ___ | ___ | ______ | _________________________ | ___________\\n____ | _____ | ___ | ___ | ______ | _________________________ | ___________\\n\\nNEXT LEVEL\\nLevel 36 turns the fixed-key A-major-pentatonic map into expressive articulation: hammer-ons, pull-offs,\\ncontrolled slides, bends, releases, and vibrato.\",\"pdf\":\"Level 35 - Practice Progression, Mastery Gate, and Log\\nAdvance by improving map accuracy and landing quality before adding speed.\\nStandard tuning. Fixed key: A major pentatonic. Frets 4-17. Use clean tone before adding gain.\\nPage 13 of 13\\nEight-phase practice progression\\n1.\\nMap all six lanes and say notes plus degrees.\\n2.\\nPlay one Module A lane at one note per click.\\n3.\\nComplete all six silent-shift cells with both pick starts.\\n4.\\nAdd one seam-slide page; count 6 tones but only 4 attacks per string.\\n5.\\nComplete Module C with finger 1 and no audible relocation.\\n6.\\nPlay the 36-note forward snake without a pause.\\n7.\\nPlay the 36-note reverse snake without a pause.\\n8.\\nLink the 72-note circuit and accent A roots, then remove the accents.\\nCounts, repair rules, and advancement\\nModule\\nSounding tones\\nPick attacks\\nA - silent lanes\\n72\\n72\\nB - seam slides\\n144\\n96\\nC - landings\\n96\\n96\\nD - linked snake\\n72\\n72\\nComplete workout\\n384\\n336\\nNOISY SHIFT: release earlier, move thumb with hand, reduce 4-6 BPM.\\nLATE SLIDE: shorten the motion and practice the anchor-to-target pair alone.\\nFRET FISHING: name and look at the destination before leaving the launch note.\\nPICK RESET: air-pick the exact 12-, 36-, or 72-note count.\\nTENSION: stop the full route and return to one string.\\nADVANCE: add 2 BPM after three clean runs; after two errors, shorten the route before forcing speed.\\nMastery gate before Level 36\\nName the six notes and degrees on every string; play all six Module A lanes with D-start and U-start; execute all 24 seam-slide phrases without an extra pick or late arrival; land on every printed destination without an audible search; complete\\nthe linked 72-note snake on two separate days; identify every A root by sight and sound; and recover the correct lane after a deliberate random stop.\\nPractice log\\nDate\\nFocus\\nD/U\\nBPM\\nClean?\\nWeak lane / seam / target\\nNext target\\nNEXT\\nLevel 36 turns the fixed-key A-major-pentatonic map into expressive articulation: hammer-ons, pull-offs, controlled slides, bends, releases, and vibrato.\",\"picking\":\"Module D: forward 36 + reverse 36 = 72 picked notes.\\nComplete Level 35 workout = 384 sounding tones / 336 pick attacks.\\n\\nSTRICT ALTERNATE PICKING\\nComplete separate D-start and U-start passes. Do not restart at a string change, station shift, seam slide,\\nrepeated destination, A root, or forward/reverse turnaround. A slide destination is sounded without a new\\npick attack and must arrive exactly on the subdivision.\",\"module_a\":\"MODULE A - SIX SILENT-SHIFT HORIZONTAL LANES\\n========================================================================================================================\\nGroup each lane into three two-note stations. Use finger 1-3 for a whole step and 1-4 for a minor third.\\nShift after the first station and after the second station. Release pressure before moving. No slide is allowed.\\n\",\"module_b\":\"========================================================================================================================\\nFor every string: pick the lower note; pick the shared anchor and slide to the upper destination; re-pick the\\ndestination and slide back to the anchor; pick the lower note. Each phrase contains 6 sounding tones but\\nonly 4 pick attacks. Use finger 3 for a two-fret slide and finger 4 for a three-fret slide.\\n\",\"module_c\":\"========================================================================================================================\\nLaunch from the lower endpoint of each string. Land on the third, fourth, fifth, and sixth lane notes in turn.\\nEach four-note cell is launch -> target -> repeated target -> launch. First pass: use finger 1 on every note.\\nNo slide is allowed. After the printed pass, begin at the upper endpoint and mirror the target order downward.\\n\",\"module_d\":\"========================================================================================================================\\nEvery segment contains six notes. Because six is even, each new string begins with the original pick-start\\norientation. Do not reset at a string change.\\n\\nFORWARD ROUTE: Low E ASC -> A DESC -> D ASC -> G DESC -> B ASC -> High e DESC\\nTransitions: E17/A16 | A4/D4 | D16/G16 | G4/B5 | B17/e17\"},\"source_options_are_distinct\":true,\"landing_task_supplement\":{\"rows\":[31,32,33,34,35,36],\"source_context\":{\"path\":\"Build/fullscope-private-a-r01/level035-r06/original-landing-context.json\",\"bytes\":16347,\"sha256\":\"549796db5bcd739abb6a6f1c01701622e8ef5f994056218554ec51b32b698f6b\"},\"cells\":24,\"existing_contacts\":96,\"additional_sounding_events\":0,\"readiness_changes\":0}}}}";
